@Composable
fun RepeatIntervalSelector(
    selectedRepeat: RepeatInterval,
    onSelect: (RepeatInterval) -> Unit
) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        val intervals = listOf(
            RepeatInterval.NONE to stringResource(R.string.interval_once),
            RepeatInterval.DAILY to stringResource(R.string.interval_daily),
            RepeatInterval.WEEKLY to stringResource(R.string.interval_weekly),
            RepeatInterval.MONTHLY to stringResource(R.string.interval_monthly)
        )

        intervals.forEach { (value, label) ->
            val isSelected = selectedRepeat == value
            val accentColor = MaterialTheme.colorScheme.primary
            Box(
                modifier = Modifier
                    .weight(1f)
                    .height(34.dp)
                    .clip(RoundedCornerShape(8.dp))
                    .background(
                        if (isSelected) accentColor.copy(alpha = 0.20f)
                        else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
                    )
                    .border(
                        width = if (isSelected) 2.dp else 1.dp,
                        color = if (isSelected) accentColor else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.1f),
                        shape = RoundedCornerShape(8.dp)
                    )
                    .clickable { onSelect(value) }
                    .testTag("repeat_$value"),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = label,
                    fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Medium,
                    fontSize = 12.sp,
                    color = if (isSelected) accentColor else MaterialTheme.colorScheme.onSurface.copy(alpha = 0.6f)
                )
            }
        }
    }
}
